/// <summary>
/// A COC extension class for EInvoice datafield of CustTable datasource of CustTable form.
/// </summary>
[ExtensionOf(formDataFieldStr(CustTable, CustTable, EInvoice))]
internal final class METCustTableFormCustTableDSeInvoice_Extension
{
}

Method.Source:
/// <summary>
///  Method to determine the behaviour of certain fields based on modification of eInvioce checkbox.
/// </summary>
public void modified()
{
    next  modified();

    FormDataObject formDataObject = any2Object(this) as FormDataObject;

    FormDataSource custTableDS = formDataObject.datasource();
    CustTable custTable = custTableDS.cursor();

    FormRun formRun = custTableDS.formRun();
    FormDataSource metCustTableDS = formRun.dataSource(formDataSourceStr(CustTable, METCustTable));

    metCustTableDS.object(fieldNum(METCustTable, eInvoiceVersionId)).allowEdit(custTable.EInvoice);

    if (custTable.EInvoice)
    {
        METCustTable metCustTable = metCustTableDS.cursor();

        if (!metCustTable.eInvoiceVersionId && metCustTable.IndustryKey)
        {
            metCustTable.eInvoiceVersionId = METIndustryKeyTable::find(metCustTable.IndustryKey).EInvoiceVersionId;
        }
    }

}
